// 共通番号3474の system 定義の表。I/O と実時刻を持たない。

const systemStatuses = new Set(['prerequisite_waiting', 'scope_waiting']);
const systemStages = new Set(['pending', 'rider', 'investigating', 'retrying', 'retried']);
const systemKinds = new Set(['attention_pending', 'usage_limit_wait']);

export function attentionActor(row) {
  if (['user', 'ai', 'system'].includes(row.nextActor)) return row.nextActor;
  return systemStatuses.has(row.status) ||
    (row.kind === 'attention' && (systemStages.has(row.state) || systemKinds.has(row.caseKind)))
    ? 'system'
    : 'ai';
}

function attentionTimestamp(value) {
  if (typeof value !== 'string' || !value.trim()) return null;
  const text = value.trim();
  const time = Date.parse(/(?:Z|[+-]\d{2}:?\d{2})$/i.test(text) ? text : `${text}Z`);
  return Number.isFinite(time) ? time : null;
}

export function attentionActivity(row) {
  if (row.kind === 'issue') return attentionTimestamp(row.updatedAt);
  if (row.kind === 'draft') return attentionTimestamp(row.messages?.at(-1)?.at) ?? attentionTimestamp(row.updatedAt);
  const times = ['updatedAt', 'detectedAt', 'finishedAt', 'startedAt']
    .map((key) => attentionTimestamp(row[key]))
    .filter((time) => time !== null);
  return times.length ? Math.max(...times) : null;
}

export function attentionCaseKey(row, index) {
  if (row.kind === 'stall' && row.causeKey) return `cause:${row.causeKey}`;
  const number = Number.isSafeInteger(row.number) ? row.number : Number.isSafeInteger(row.issue) ? row.issue : null;
  if (row.project && number !== null) return `issue:${row.project}#${number}`;
  const draftId = [row.kind === 'draft' ? row.id : null, row.draftId, row.consultationId].find(
    (value) => typeof value === 'string' && value.trim(),
  );
  if (draftId) return `draft:${draftId}`;
  return `row:${index}`;
}

export function splitAttention(rows, { now, waitLimitMinutes = 1440 }) {
  const nowMs = typeof now === 'number' ? now : now instanceof Date ? now.getTime() : attentionTimestamp(now);
  if (nowMs === null || !Number.isFinite(nowMs)) throw Error('now は有効な時刻を指定してください');
  if (!Number.isFinite(waitLimitMinutes) || waitLimitMinutes <= 0)
    throw Error('waitLimitMinutes は正の数を指定してください');
  const groups = new Map();
  rows.forEach((row, index) => {
    const key = attentionCaseKey(row, index);
    const group = groups.get(key) || [];
    group.push(row);
    groups.set(key, group);
  });
  const attention = [],
    waiting = [],
    stopped = [];
  for (const [key, group] of groups) {
    const times = group.map(attentionActivity).filter((time) => time !== null);
    const lastMs = times.length ? Math.max(...times) : null;
    const elapsedMinutes = lastMs === null ? null : Math.max(0, (nowMs - lastMs) / 60000);
    const actors = group.map(attentionActor);
    const nextActor = actors.includes('ai') ? 'ai' : actors.includes('user') ? 'user' : 'system';
    const entry: Record<string, any> = {
      key,
      rows: group,
      nextActor,
      elapsedMinutes,
      lastActivityAt: lastMs === null ? null : new Date(lastMs).toISOString(),
    };
    if (key.startsWith('cause:')) {
      entry.count = group.length;
      entry.members = group.map((row) => ({
        project: row.project ?? null,
        number: row.number ?? row.issue ?? null,
        desk: row.desk ?? null,
        id: row.id ?? null,
      }));
    }
    if (group.some((row) => row.kind === 'issue' && row.status === 'stopped')) stopped.push(entry);
    else if (nextActor === 'system' && (elapsedMinutes === null || elapsedMinutes <= waitLimitMinutes)) {
      entry.reasons = [
        ...new Set(group.map((row) => row.reason || row.caseKind || row.state || row.status || 'system')),
      ];
      waiting.push(entry);
    } else {
      if (nextActor === 'system') {
        entry.nextActor = 'ai';
        entry.waitExceeded = true;
      }
      attention.push(entry);
    }
  }
  return {
    attention,
    waiting,
    stopped,
    counts: {
      attention: attention.length,
      waiting: waiting.length,
      stopped: stopped.length,
    },
  };
}
